import { invoke as probeInvoke } from '@tauri-apps/api/core'
import { editorTimings as probeTimings } from './editor-performance'
const probeSleep = ms => new Promise(resolve => setTimeout(resolve, ms))
async function probeUntil(check, label, limit = 30000) {
  const start=performance.now()
  while(!check()) { if(performance.now()-start>limit)throw new Error('Timeout: '+label); await probeSleep(20) }
}
async function probePost(route, data) {
  const res=await fetch('/'+route,{method:'POST',headers:{'content-type':'application/json','x-fixture-token':PROBE_TOKEN},body:JSON.stringify(data)})
  if(!res.ok)throw new Error('Controller '+route+': '+await res.text())
  return res.json()
}
async function probeCheckpoint(stage, extra={}) {
  if(document.visibilityState!=='visible')throw new Error('WebView is hidden at '+stage)
  const app=document.querySelector('#app').__vue_app__, stores=app.config.globalProperties.$pinia._s
  const library=stores.get('library'), editor=stores.get('editor')
  return probePost('checkpoint',{stage,visibility:document.visibilityState,focused:document.hasFocus(),viewport:{width:innerWidth,height:innerHeight,dpr:devicePixelRatio},rows:document.querySelectorAll('.sample-list .row').length,canvases:document.querySelectorAll('canvas').length,heapAvailable:!!performance.memory,heapBytes:performance.memory?.usedJSHeapSize??null,library:library?.pageDiagnostics(),total:library?.total,editor:{open:editor?.open,frames:editor?.state?.frames??0,processing:editor?.processing,dirty:editor?.state?.dirty},timings:probeTimings.snapshot(),native:await probeInvoke('debug_snapshot'),...extra})
}
async function probeScenario() {
  await getCurrentWindow().show()
  await getCurrentWindow().setFocus()
  await probeUntil(()=>document.visibilityState==='visible','visible WebView')
  const app=document.querySelector('#app').__vue_app__, stores=app.config.globalProperties.$pinia._s
  const library=stores.get('library'), editor=stores.get('editor')
  await probeUntil(()=>library.total===100000 && document.querySelector('.sample-list .row'),'100k real SQLite library')
  await probeSleep(1200)
  await probeCheckpoint('library-loaded')
  const scroll=document.querySelector('.sample-list [tabindex="0"][aria-label="All samples"]')
  if(!scroll||scroll.scrollHeight<3000000)throw new Error('Missing library viewport')
  const frameGaps=[],start=performance.now();let last,raf
  function frame(t){if(last!==undefined)frameGaps.push(t-last);last=t;raf=requestAnimationFrame(frame)}
  raf=requestAnimationFrame(frame)
  for(let i=1;i<=35;i++){scroll.scrollTop=i*90000;await probeSleep(80)}
  await probeSleep(1200);cancelAnimationFrame(raf)
  await probeCheckpoint('library-scrolled',{elapsedMs:performance.now()-start,frameGapsMs:frameGaps,scrollTop:scroll.scrollTop})
  for(let i=0;i<10;i++){
    library.query='Sample'+String(i*9000).padStart(8,'0')
    await probeSleep(10)
    library.scope={kind:'favorites'}
    library.query=''
    await probeSleep(10)
    library.scope={kind:'all'}
  }
  await probeSleep(1500)
  scroll.scrollTop=0
  await probeUntil(()=>library.total===100000 && document.querySelector('.sample-list .row[data-index="0"]'),'restored scope')
  await probeCheckpoint('library-restored',{rapidScopeChanges:10})
  for(const [label,id,seconds] of [['short',1,30],['long',2,1200]]){
    probeTimings.reset()
    await editor.openSample({id,name:label+' synthetic',path:PROBE_AUDIO+'/'+label+'.wav',ext:'wav',bpm:120})
    await probeUntil(()=>!editor.loading && editor.state?.frames===seconds*44100 && document.querySelector('[data-editor-panel] canvas'),'native editor '+label)
    await probeUntil(()=>probeTimings.snapshot().some(m=>m.name==='editor_wave'&&m.calls>0),'native waveform '+label)
    await probeSleep(1300)
    await probeCheckpoint('editor-'+label+'-loaded')
    const actions=[]
    for(let n=0;n<10;n++){
      editor.selection={start:0,end:3*44100}
      const t=performance.now();editor.fade('out')
      await probeUntil(()=>!editor.processing && editor.state.canUndo,'fade completion')
      const stateMs=performance.now()-t
      await probeSleep(100)
      await editor.undo()
      await probeUntil(()=>!editor.processing && !editor.state.dirty,'undo completion')
      actions.push({iteration:n+1,commandToStateMs:stateMs})
      await probeSleep(100)
    }
    await probeSleep(1200)
    await probeCheckpoint('editor-'+label+'-edited',{actions})
    if(!await editor.closeEmbedded())throw new Error('Cannot close clean editor')
    await probeSleep(1500)
    await probeCheckpoint('editor-'+label+'-closed')
  }
  await probePost('finished',{ok:true,visibility:document.visibilityState,timings:probeTimings.snapshot()})
}
async function probeStart(){
  await getCurrentWindow().show()
  await getCurrentWindow().setFocus()
  const info=await probeInvoke('app_info')
  if(!info.dbPath.includes('fonicca-foreground-'))throw new Error('Unsafe native profile path')
  await probePost('seed',{info})
  await mount()
  await probeScenario()
}
probeStart().catch(async error=>{console.error(error);try{await probePost('finished',{ok:false,error:String(error),visibility:document.visibilityState})}catch{}})

