from pathlib import Path
from functools import partial
from http.server import SimpleHTTPRequestHandler, ThreadingHTTPServer
import json,sqlite3,subprocess,threading,time,re,os,hashlib,sys
root=Path(Path('/tmp/fonicca-foreground-root.txt').read_text())
token=(root/'token').read_text()
reports=[];done=threading.Event();seeded=False;guard=threading.Lock();host=None

def locked():
 text=subprocess.check_output(['ioreg','-n','Root','-d1'],text=True)
 m=re.search(r'"IOConsoleLocked" = (Yes|No)',text)
 if not m: raise RuntimeError('Cannot verify desktop state')
 return m[1]=='Yes'

def processes():
 text=subprocess.check_output(['ps','-axo','pid=,ppid=,rss=,comm='],text=True)
 rows=[]
 for line in text.splitlines():
  p=line.strip().split(None,3)
  if len(p)==4:
   rows.append({'pid':int(p[0]),'parent':int(p[1]),'rssBytes':int(p[2])*1024,'name':p[3]})
 return rows

def webkit(p):return 'com.apple.WebKit.'in p['name']
if locked():raise SystemExit('Desktop is locked: do not start a foreground profile')
prior={p['pid']for p in processes()if webkit(p)}

def seed(info):
 global seeded
 if Path(info['dbPath']).resolve()!=(root/'data/library.db').resolve():raise RuntimeError('Unexpected app data directory')
 if Path(info['modelsDir']).resolve()!=(root/'data/models').resolve():raise RuntimeError('Unexpected model directory')
 with guard:
  if seeded:return {'seeded':True}
  c=sqlite3.connect(root/'data/library.db',timeout=30)
  def natural(a,b):
   def key(s):return [(1,int(p),len(p))if p.isdigit()else(0,p.lower())for p in re.split(r'(\d+)',s)]
   x,y=key(a),key(b);return (x>y)-(x<y)
  c.create_collation('FONICCA_NATURAL',natural)
  if c.execute('select count(*) from samples').fetchone()[0]!=0 or c.execute('select count(*) from sources').fetchone()[0]!=0:raise RuntimeError('Private database was not empty')
  c.execute('insert into sources(id,path,added_at) values(1,?,?)',(str(root/'audio'),int(time.time())))
  rows=[]
  for i in range(1,100001):
   if i<=2:
    label,seconds=('short',30)if i==1 else('long',1200)
    path=root/'audio'/f'{label}.wav';name=f'000 {label} synthetic';size=path.stat().st_size
   else:
    seconds=1;path=root/'audio/metadata'/f'{i:08d}.wav';name=f'Sample{i:08d}';size=100
   rows.append((i,str(path),name,'wav',size,1,float(seconds),44100,2,32,i,1,'long'if seconds>1 else'oneshot',999,1 if i%7==0 else 0))
  c.executemany('insert into samples(id,source_id,path,name,ext,size,mtime,duration,sample_rate,channels,bit_depth,fingerprint,analysis_version,kind,category_version,favorite) values(?,1,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',rows)
  c.commit();count=c.execute('select count(*) from samples').fetchone()[0];c.close()
  seeded=True
  return {'seeded':True,'count':count}

class Handler(SimpleHTTPRequestHandler):
 def log_message(self,fmt,*args):
  with (root/'http.log').open('a')as f:f.write((fmt%args)+'\n')
 def send_json(self,status,value):
  data=json.dumps(value).encode();self.send_response(status);self.send_header('Content-Type','application/json');self.send_header('Content-Length',str(len(data)));self.end_headers();self.wfile.write(data)
 def do_GET(self):
  if self.path=='/favicon.ico':self.send_response(204);self.end_headers();return
  return super().do_GET()
 def do_POST(self):
  try:
   if self.headers.get('x-fixture-token')!=token:raise RuntimeError('Wrong private fixture token')
   value=json.loads(self.rfile.read(int(self.headers['Content-Length'])))
   if self.path=='/seed':return self.send_json(200,seed(value['info']))
   if self.path=='/checkpoint':
    if locked():raise RuntimeError('Desktop locked during observation')
    if value.get('visibility')!='visible':raise RuntimeError('Hidden observation')
    current=processes();cohort=[p for p in current if p['pid']==host.pid or (webkit(p)and p['pid']not in prior)]
    if not any('WebContent'in p['name']for p in cohort):raise RuntimeError('Cannot attribute a new WebContent process')
    command=['footprint']
    for p in cohort:command+=['-p',str(p['pid'])]
    target=root/(value['stage']+'-footprint.json');command+=['-j',str(target),'--noCategories','-f','bytes']
    r=subprocess.run(command,capture_output=True,text=True,timeout=25)
    if r.returncode:raise RuntimeError('footprint failed: '+r.stderr[-500:])
    report={**value,'screenLocked':False,'capturedAt':time.time(),'processes':cohort,'footprint':json.loads(target.read_text())}
    reports.append(report);(root/'checkpoints.json').write_text(json.dumps(reports,indent=2))
    print(json.dumps({'checkpoint':value['stage'],'rows':value['rows'],'frames':value['editor']['frames'],'visibility':value['visibility'],'processes':[(p['pid'],p['name'].split('/')[-1],p['rssBytes'])for p in cohort]}),flush=True)
    return self.send_json(200,{'captured':True})
   if self.path=='/finished':
    (root/'finished.json').write_text(json.dumps(value,indent=2));done.set();return self.send_json(200,{'finished':True})
   raise RuntimeError('Unknown route')
  except Exception as e:
   print('Controller error: '+str(e),flush=True);self.send_json(500,{'error':str(e)})

server=ThreadingHTTPServer(('127.0.0.1',1435),partial(Handler,directory=str(root/'frontend')))
threading.Thread(target=server.serve_forever,daemon=True).start()
binary=root/'fonicca-profile';data=binary.read_bytes()
if b'app.fonicca.performance-fixture'not in data or str(root/'data').encode()not in data:raise SystemExit('Refusing an unsafe native binary')
with (root/'native-run.log').open('w')as log:
 host=subprocess.Popen([str(binary)],stdout=log,stderr=subprocess.STDOUT,cwd=root)
 (root/'host-pid').write_text(str(host.pid))
 print('Isolated native host PID '+str(host.pid),flush=True)
 try:
  deadline=time.monotonic()+300
  while not done.wait(.5):
   if host.poll()is not None:raise RuntimeError('Native host exited '+str(host.returncode))
   if time.monotonic()>deadline:raise RuntimeError('Foreground profile timed out')
  finished=json.loads((root/'finished.json').read_text())
  if not finished.get('ok'):raise RuntimeError('Foreground fixture: '+finished.get('error','failed'))
 finally:
  host.terminate()
  try:host.wait(timeout=8)
  except subprocess.TimeoutExpired:host.kill();host.wait()
  server.shutdown()
cohort={p['pid']for stage in reports for p in stage['processes']}
deadline=time.monotonic()+35
while time.monotonic()<deadline:
 remaining=cohort&{p['pid']for p in processes()}
 if not remaining:break
 time.sleep(.5)
result={'schema':1,'status':'foreground-observations-completed','identifier':'app.fonicca.performance-fixture','appDataOverride':str(root/'data'),'incognito':True,'backend':'Real native IPC and isolated SQLite, no mockIPC. 100k rows: two private synthetic float WAVs and 99998 metadata-only rows. No model inference or audible playback. Sources inserted after startup to avoid scanning metadata-only paths.','beforeWebKitPids':sorted(prior),'nativeHostPid':host.pid,'cohortPids':sorted(cohort),'cohortRemainingAfterHostExit':sorted(remaining),'binarySha256':hashlib.sha256(data).hexdigest(),'checkpointCount':len(reports),'checkpoints':reports,'finished':finished,'limits':['One macOS ARM64 dev-test profile GUI observation; no before/after WebView comparison or cross-platform guarantee.','Metadata rows are synthetic; only two audio paths exist. Library operations and editor PCM/waveform rendering use real native IPC.','Per-process ps RSS and footprint have different accounting. PCM bytes include mmap-backed storage and must not be added to RSS. Do not sum process RSS as disjoint physical memory.','WebKit attribution uses newly appearing PIDs relative to the before-launch snapshot and validates their disappearance after stopping only this host.','Action-to-state samples include polling; IPC timing summaries are recorded separately. Canvas submission is not GPU completion.','No real audio-device playback, external models, saves to user files, app installation, release or publication.']}
(root/'result.json').write_text(json.dumps(result,indent=2))
print(json.dumps({'complete':True,'checkpoints':len(reports),'remainingPids':sorted(remaining),'report':str(root/'result.json')}),flush=True)
